<?php
declare(strict_types=1);requireRole($user,['provincial_admin']);
if(!ChurchPortal::officerRegistrationReady($db)){echo '<div class="notice">Upgrade church registration in <a href="?page=settings">Portal settings</a> before managing representatives.</div>';return;}
$q=is_string($_GET['q']??null)&&preg_match('/^.{0,100}$/us',$_GET['q'])?trim($_GET['q']):'';$status=in_array($_GET['status']??'', ['active','suspended'],true)?$_GET['status']:'';
$where="u.role IN ('parish_officer','area_rep','zonal_rep')";$params=[];
if($q!==''){$where.=" AND (u.full_name LIKE ? ESCAPE '!' OR u.email LIKE ? ESCAPE '!' OR h.node_name LIKE ? ESCAPE '!')";$term='%'.strtr($q,['!'=>'!!','%'=>'!%','_'=>'!_']).'%';$params=[$term,$term,$term];}
if($status!==''){$where.=' AND u.is_suspended=?';$params[]=$status==='suspended'?1:0;}
$from='users u LEFT JOIN church_hierarchy h ON h.id=u.hierarchy_id';$s=$db->prepare("SELECT COUNT(*) FROM $from WHERE $where");$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/12));$number=min($pages,max(1,(int)(is_scalar($_GET['rep_page']??1)?($_GET['rep_page']??1):1)));$offset=($number-1)*12;
$s=$db->prepare("SELECT u.id,u.full_name,u.email,u.role,u.is_suspended,h.node_name FROM $from WHERE $where ORDER BY u.full_name,u.id LIMIT 12 OFFSET $offset");$s->execute($params);$reps=$s->fetchAll();
$edit=null;if(!empty($_GET['edit'])&&is_scalar($_GET['edit'])){try{$edit=RepresentativeManager::target($db,(int)$_GET['edit']);}catch(RuntimeException){echo '<div class="notice">Representative not found.</div>';}}
$phone='';if($edit){$s=$db->prepare('SELECT phone FROM officer_profiles WHERE user_id=?');$s->execute([$edit['id']]);$phone=(string)$s->fetchColumn();}
$directory=ChurchPortal::directory($db);
$pendingCount=(int)$db->query("SELECT COUNT(*) FROM church_registrations WHERE status='pending'")->fetchColumn();
?>
<nav class="rep-shortcuts" aria-label="Representative sections"><a class="primary" href="#pending-reps">Pending approvals <span class="rep-count"><?= $pendingCount ?></span></a><a class="secondary" href="#registered-reps">Registered reps</a><a class="secondary" href="#representative-editor"><?= $edit?'Edit representative':'Add representative' ?></a></nav>
<?php require __DIR__.'/registrations-view.php'; ?>
<details class="rep-editor-disclosure" <?= $edit?'open':'' ?>><summary><?= $edit?'Edit representative':'Add a representative manually' ?></summary>
<div class="notice">Public registration is <strong><?= setting($db,'registration_enabled')==='1'?'open':'closed' ?></strong>. Applications still require your approval. <a class="text-link" href="?page=settings">Registration settings →</a></div>
<section class="panel form-panel" id="representative-editor"><h2><?= $edit?'Edit representative':'Add representative' ?></h2><p class="muted">Roles follow the selected church level. Share credentials through a trusted channel, never by email. Your admin transaction PIN authorizes changes.</p>
<form method="post" class="form-grid"><?php hiddenAction('representative_manage') ?><input type="hidden" name="operation" value="save"><input type="hidden" name="rep_id" value="<?= (int)($edit['id']??0) ?>">
<label>Full name<input name="full_name" required maxlength="100" value="<?= e($edit['full_name']??'') ?>"></label><label>Email<input name="email" type="email" maxlength="150" required value="<?= e($edit['email']??'') ?>"></label><label>Phone<input name="phone" type="tel" required maxlength="25" value="<?= e($phone) ?>"></label>
<label>Church<select name="hierarchy_id" data-unit-search required><option value="">Choose Parish, Area or Zone</option><?php foreach($directory as $church): ?><option value="<?= (int)$church['id'] ?>" <?= (int)($edit['hierarchy_id']??0)===(int)$church['id']?'selected':'' ?>><?= e($church['node_name'].' · '.$church['node_type'].' · '.($church['parent_name']??'Province')) ?></option><?php endforeach ?></select></label>
<label><?= $edit?'New password (blank = unchanged)':'Initial password' ?><input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" <?= $edit?'':'required' ?>></label><label>Your transaction PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" required autocomplete="off"></label><button class="primary">Save representative</button><?php if($edit): ?><a href="?page=representatives">Cancel / add new</a><?php endif ?></form></section></details>
<section class="panel" id="registered-reps"><div class="panel-heading"><h2>Registered representatives</h2><span><?= $total ?> matching accounts</span></div><form method="get" class="history-filters"><input type="hidden" name="page" value="representatives"><label>Search name, email or church<input type="search" name="q" value="<?= e($q) ?>" maxlength="100"></label><label>Status<select name="status"><option value="">All</option><option value="active" <?= $status==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= $status==='suspended'?'selected':'' ?>>Suspended</option></select></label><button class="secondary">Search</button><a href="?page=representatives">Reset</a></form>
<?php if(!$reps): ?><p class="empty-inline">No representatives match these filters. Pending applications are shown above.</p><?php endif ?>
<div class="registered-rep-grid"><?php foreach($reps as $rep): ?><article class="form-panel representative-card"><h3><?= e($rep['full_name']) ?> · <?= $rep['is_suspended']?'Suspended':'Active' ?></h3><p><?= e($rep['email'].' · '.$rep['node_name'].' · '.str_replace('_',' ',$rep['role'])) ?></p><a class="text-link" href="?page=representatives&amp;edit=<?= (int)$rep['id'] ?>#representative-editor">Edit details / password →</a>
<details><summary>Account actions</summary><p class="small muted">Delete is refused for payment/review history. Impersonation is read-only and cannot target privileged or suspended accounts.</p>
<form method="post" class="form-grid"><?php hiddenAction('representative_manage') ?><input type="hidden" name="rep_id" value="<?= (int)$rep['id'] ?>"><label>Action<select name="operation"><option value="<?= $rep['is_suspended']?'unsuspend':'suspend' ?>"><?= $rep['is_suspended']?'Unsuspend':'Suspend' ?></option><option value="delete">Delete unused account</option></select></label><label>Type DELETE only if deleting<input name="confirm_delete" autocomplete="off"></label><label>Your transaction PIN<input name="pin" type="password" pattern="[0-9]{4}" inputmode="numeric" autocomplete="off" required></label><button class="secondary">Apply account action</button></form>
<?php if(!$rep['is_suspended']): ?><form method="post" class="form-grid"><?php hiddenAction('impersonate') ?><input type="hidden" name="rep_id" value="<?= (int)$rep['id'] ?>"><label>Your transaction PIN<input name="pin" type="password" pattern="[0-9]{4}" inputmode="numeric" autocomplete="off" required></label><button class="secondary">View as representative (read-only)</button></form><?php endif ?></details></article><?php endforeach ?></div>
<nav class="history-pagination" aria-label="Representative pages"><?php if($number>1): ?><a href="?<?= e(http_build_query(['page'=>'representatives','q'=>$q,'status'=>$status,'rep_page'=>$number-1])) ?>">← Previous</a><?php endif ?><span>Page <?= $number ?> of <?= $pages ?></span><?php if($number<$pages): ?><a href="?<?= e(http_build_query(['page'=>'representatives','q'=>$q,'status'=>$status,'rep_page'=>$number+1])) ?>">Next →</a><?php endif ?></nav></section>
